template <bool Purposed, class Result>
NoteRequest<Purposed, Result>& NoteRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

class query_factory {
    ContextBinding binding_;

public:
    explicit query_factory(UserContext& user_context) : binding_(user_context) {}

    NoteRequest<false> notesMinimal() const {
        return NoteRequest<false>(binding_.get(), true);
    }

    NoteRequest<false> notes() const {
        return NoteRequest<false>(binding_.get());
    }

    NoteRequest<false> notesWithChildren() const {
        return NoteRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }
};
